#[test]
fn find_all_refs_root_of_referenced_project() {
	run_test(|t| {
		for disable_source_of_project_reference_redirect in vec![false, true] {
			run_subtest(&mut t, format!("{}{}", "TestFindAllRefsRootOfReferencedProject", tsc_core::if_else(disable_source_of_project_reference_redirect, "DeclarationMaps", "")), |t| {
				let mut content = format!(r#"
// @stateBaseline: true
%s
// @Filename: src/common/input/keyboard.ts
function bar() { return "just a random function so .d.ts location doesnt match"; }
export function /*keyboard*/evaluateKeyboardEvent() { }
// @Filename: src/common/input/keyboard.test.ts
import { evaluateKeyboardEvent } from 'common/input/keyboard';
function testEvaluateKeyboardEvent() {
	return evaluateKeyboardEvent();
}
// @Filename: src/terminal.ts
/*terminal*/import { evaluateKeyboardEvent } from 'common/input/keyboard';
function foo() {
	return evaluateKeyboardEvent();
}
// @Filename: /src/common/tsconfig.json
{
	"compilerOptions": {
		"composite": true,
		"declarationMap": true,
		"outDir": "../../out",
		"disableSourceOfProjectReferenceRedirect": %v,
		"paths": {
			"*": ["../*"],
		},
	},
	"include": ["./\**/*"]
}
// @Filename: src/tsconfig.json
{
	"compilerOptions": {
		"composite": true,
		"declarationMap": true,
		"outDir": "../out",
		"disableSourceOfProjectReferenceRedirect": %v,
		"paths": {
			"common/*": ["./common/*"],
		},
		"tsBuildInfoFile": "../out/src.tsconfig.tsbuildinfo"
	},
	"include": ["./\**/*"],
	"references": [
		{ "path": "./common" },
	],
}"#, tsc_core::if_else(disable_source_of_project_reference_redirect, "// @tsc: --build /src/tsconfig.json", ""), disable_source_of_project_reference_redirect, disable_source_of_project_reference_redirect);
				let mut f = tsc_fourslash::new_fourslash(&t_name(), "", None, content);
				f.go_to_marker("keyboard");
				f.go_to_marker("terminal");
				f.verify_baseline_find_all_references(&["keyboard".into()]);
			});
		}
	});
}

